abstract class Shape {
    abstract double area();
    void describe() {                      // regular, concrete method
        System.out.println("Area: " + area());
    }
}
class Circle extends Shape {
    double radius;
    Circle(double r) { radius = r; }
    double area() { return Math.PI * radius * radius; }
}

interface Payable {
    double calculatePay();
    default void printPay() {              // default method with a body
        System.out.println("Pay: " + calculatePay());
    }
}
class Freelancer implements Payable {
    public double calculatePay() { return 500; }
}

public class Main {
    public static void main(String[] args) {
        new Circle(2).describe();
        new Freelancer().printPay();       // inherited default method, no override needed
    }
}
